// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DO WOOCOMMERCE (META_DATA, BILLING, CUSTOM FIELDS)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

const billing = body.billing || {};
let rawPhone = (billing.phone || body.shipping?.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = `${billing.first_name || 'Cliente'} ${billing.last_name || ''}`.trim();
const clienteEmail = (billing.email || '').trim().toLowerCase();

// Extração de CPF/CNPJ de plugins brasileiros comuns (ex: WooCommerce Extra Checkout Fields)
const meta = body.meta_data || [];
let clienteDoc = '';
meta.forEach(m => {
  if (['_billing_cpf', 'billing_cpf', '_billing_cnpj', 'billing_cnpj', 'cpf', 'cnpj'].includes(m.key)) {
    clienteDoc = (m.value || '').toString().replace(/\D/g, '');
  }
});

const numeroPedido = parseInt(body.number || body.id || Date.now(), 10);
const valorTotal = parseFloat(body.total || 0);
const valorFrete = parseFloat(body.shipping_total || 0);
const status = (body.status || 'pending').toLowerCase();

let statusOperacional = 'Pendente';
if (['processing', 'completed'].includes(status)) {
  statusOperacional = 'Pago';
} else if (['cancelled', 'failed', 'refunded'].includes(status)) {
  statusOperacional = 'Cancelado';
} else if (['on-hold', 'pending'].includes(status)) {
  statusOperacional = (body.payment_method_title || '').toLowerCase().includes('boleto') ? 'Pendente_Boleto' : 'Pendente_PIX';
}

const lineItems = (body.line_items || []).map(li => ({
  produto_nome: li.name || 'Produto',
  sku: li.sku || 'WOO_SKU',
  quantidade: parseInt(li.quantity || 1, 10),
  preco_venda: parseFloat(li.total || 0)
}));

const dedupHash = crypto.createHash('sha256').update(`woocommerce_${numeroPedido}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_doc: clienteDoc,
    valor_total: valorTotal,
    valor_frete: valorFrete,
    status_operacional: statusOperacional,
    line_items: lineItems
  }
}];
